import "core-js/modules/es6.typed.uint8-array";
import { resourceDetail, resourceRecentView, resourceLasted } from "@/api/ictOperation/index";
export default {
  data: function data() {
    return {
      detailForm: {},
      hotFileList: [],
      newFileList: [],
      showTextBtn: false,
      isExpand: true
    };
  },
  mounted: function mounted() {
    this.getDetail(this.$route.query.id);
    this.getRecentView();
  },
  methods: {
    base64ToUrl: function base64ToUrl(data) {
      var base64 = data;
      var bstr = atob(base64);
      var n = bstr.length;
      var u8arr = new Uint8Array(n);
      while (n--) {
        u8arr[n] = bstr.charCodeAt(n);
      }
      var blob = new Blob([u8arr], {
        type: 'application/pdf;chartset=UTF-8'
      });
      var url = window.URL.createObjectURL(blob);
      return url;
    },
    getDetail: function getDetail(id) {
      var _this = this;
      this.pageLoading = true;
      resourceDetail({
        id: id
      }).then(function (res) {
        // console.log(1231, this.base64ToUrl(res.data.fileOutputStream))
        // res.data.fileOutputStream = this.base64ToUrl(res.data.fileOutputStream)

        _this.detailForm = res.data;
        _this.pageLoading = false;
        _this.$nextTick(function () {
          var contentBox = document.getElementById('textContent');
          if (contentBox.scrollWidth > contentBox.clientWidth) {
            _this.showTextBtn = true;
          } else {
            _this.showTextBtn = false;
          }
          var detailInfo = document.getElementsByClassName('detail_info');
          var detailContent = document.getElementsByClassName('detail_content');
          var detailLeft = document.getElementsByClassName('detail_left');
          detailContent[0].style.height = detailLeft[0].offsetHeight - detailInfo[0].offsetHeight - 40 + 'px';
        });
      });
    },
    getRecentView: function getRecentView() {
      var _this2 = this;
      var tag;
      if (this.$route.query.type == '文档') tag = '0';else tag = '1';
      resourceRecentView({
        tag: tag
      }).then(function (res) {
        _this2.hotFileList = res.data;
      });
      resourceLasted({
        tag: tag
      }).then(function (res) {
        _this2.newFileList = res.data;
      });
    },
    fullScreen: function fullScreen() {
      window.open(this.detailForm.path);
    },
    seeDetail: function seeDetail(item) {
      this.detailForm = {};
      this.showTextBtn = false;
      this.isExpand = true;
      var contentBox = document.getElementById('textContent');
      contentBox.style.whiteSpace = 'nowrap';
      contentBox.style.overflow = 'hidden';
      this.getDetail(item.id);
    },
    handleShowText: function handleShowText() {
      this.isExpand = !this.isExpand;
      var contentBox = document.getElementById('textContent');
      if (this.isExpand) {
        contentBox.style.whiteSpace = 'nowrap';
        contentBox.style.overflow = 'hidden';
      } else {
        contentBox.style.whiteSpace = 'wrap';
        contentBox.style.overflow = 'inherit';
      }
      this.$nextTick(function () {
        var detailInfo = document.getElementsByClassName('detail_info');
        var detailContent = document.getElementsByClassName('detail_content');
        var detailLeft = document.getElementsByClassName('detail_left');
        detailContent[0].style.height = detailLeft[0].offsetHeight - detailInfo[0].offsetHeight - 40 + 'px';
      });
    }
  }
};
